messages.content:
Tool response:
Tool: search_vacation_rentals
Description: Search Vacation Rentals
Parameters:
    {
      "type": "object",
      "properties": {
        "location": {
          "type": "string",
          "description": "Location to search for rentals (e.g., 'Sedona, Arizona')",
          "title": "Location"
        },
        "check_in": {
          "type": "string",
          "description": "Check-in date in YYYY-MM-DD format",
          "title": "Check In"
        },
        "check_out": {
          "type": "string",
          "description": "Check-out date in YYYY-MM-DD format",
          "title": "Check Out"
        },
        "guests": {
          "type": "integer",
          "description": "Number of guests",
          "title": "Guests"
        }
      },
      "required": [
        "location",
        "check_in",
        "check_out",
        "guests"
      ]
    }
